```python
def longest_palindrome(s):
    if not s:
        return ''
    start, end = 0, 0
    for i in range(len(s)):
        l1, r1 = expand(s, i, i)
        l2, r2 = expand(s, i, i + 1)
        for l, r in ((l1, r1), (l2, r2)):
            if r - l > end - start:
                start, end = l, r
    return s[start:end + 1]

def expand(s, lo, hi):
    while lo >= 0 and hi < len(s) and s[lo] == s[hi]:
        lo -= 1
        hi += 1
    return lo + 1, hi - 1
```

